import assert from 'node:assert/strict';
import type {Page} from 'playwright';
import type {PrismaClient} from '@prisma/client';
export async function verifyCustomMetrics(page:Page,origin:string,workspaceId:string,db:PrismaClient,check:(page:Page,phase:string)=>Promise<void>){
 const root=origin+'/dashboard/app/workspaces/'+workspaceId;
 await page.setViewportSize({width:1280,height:900});await page.goto(root+'/metrics');await page.getByRole('heading',{name:'Custom metrics',exact:true}).waitFor();await page.getByLabel('Metric dataset',{exact:true}).selectOption({label:'Browser orders'});await page.getByLabel('Metric name',{exact:true}).fill('Browser contribution');await page.getByLabel('Business meaning',{exact:true}).fill('Revenue remaining after the confirmed cost of goods sold.');await page.getByLabel('Formula',{exact:true}).fill('REVENUE - COST');await page.getByLabel('Result format',{exact:true}).selectOption('CURRENCY');await page.getByRole('button',{name:'Preview formula',exact:true}).click();await page.getByText('Formula preview: $210.00',{exact:true}).waitFor();await page.getByLabel('I reviewed the business meaning, input treatments, reporting period and result.',{exact:true}).check();await page.getByRole('button',{name:'Save custom metric',exact:true}).click();await page.getByRole('button',{name:'Edit Browser contribution',exact:true}).waitFor();
 await page.getByRole('button',{name:'Edit Browser contribution',exact:true}).click();await page.getByLabel('Metric name',{exact:true}).fill('Browser contribution margin');await page.getByLabel('Formula',{exact:true}).fill('(REVENUE - COST) / REVENUE');await page.getByLabel('Result format',{exact:true}).selectOption('PERCENT');await page.getByRole('button',{name:'Preview formula',exact:true}).click();await page.getByText('Formula preview: 60%',{exact:true}).waitFor();await page.getByLabel('I reviewed the business meaning, input treatments, reporting period and result.',{exact:true}).check();await page.getByRole('button',{name:'Save custom metric',exact:true}).click();await page.getByRole('button',{name:'Edit Browser contribution margin',exact:true}).waitFor();
 await check(page,'custom-formula-metrics-desktop');await page.setViewportSize({width:390,height:844});await check(page,'custom-formula-metrics-mobile');assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'Custom metrics page overflows mobile viewport');await page.setViewportSize({width:1280,height:900});
 const metric=await db.dashboardMetricDefinition.findFirstOrThrow({where:{workspaceId,name:'Browser contribution margin'}});assert.equal((metric.definition as {preview:{value:string}}).preview.value,'0.6');assert.equal(await db.dashboardMetricComponent.count({where:{metricId:metric.id}}),2);
 page.once('dialog',d=>d.accept());await page.getByRole('button',{name:'Delete Browser contribution margin',exact:true}).click();await page.getByText('Custom metric deleted.',{exact:true}).waitFor();assert.equal(await db.dashboardMetricDefinition.count({where:{id:metric.id}}),0);
 console.log('PASS: governed custom formula preview, create/edit/delete, business meaning confirmation, retained component lineage, exact saved value and two desktop/mobile accessibility scans.');
}
